  models.forEach(function (m) {
    m.skus.forEach(function (k) {
      var id = m.id + (k[0] ? '-' + k[0].toLowerCase() : '');
      devices.push({ id: id, model: m.id, maker: m.maker, name: m.name + (k[0] ? ' ' + k[0] : ''), cap: k[0], price: k[1], special: !!m.special, only: m.only || '' });
      if (m.special) return;
      var lg = k[2], s = {};
      ['skt', 'kt', 'lgu'].forEach(function (c) {
        if (m.only && m.only !== c) return;
        var v = (m.sub && m.sub[c]) || lg;
        if (v) s[c] = v.slice();
      });
      subsidy[id] = s;
    });
    delete m.skus; delete m.sub;
  });

