    if (extra) desc.push(extra);
    plans.push({ id: carrier + '-' + plans.length, carrier: carrier, name: name, fee: fee, data: unl ? '무제한' : data + (speed ? ' + ' + speed : ''), tier: tierOf(fee), desc: desc.join('\n') });
